#include "GltfAssetReader.h"
namespace nexo {
namespace { std::uint32_t u32(const std::uint8_t*p){return static_cast<std::uint32_t>(p[0])|(static_cast<std::uint32_t>(p[1])<<8U)|(static_cast<std::uint32_t>(p[2])<<16U)|(static_cast<std::uint32_t>(p[3])<<24U);} bool has(const std::string&s,const char*n){return s.find(n)!=std::string::npos;} }
GltfInspection inspectGltf(const std::uint8_t*b,std::size_t n){GltfInspection out;if(!b||n==0){out.message="Empty asset";return out;}if(n>=12&&u32(b)==0x46546C67U){out.binaryGlb=true;if(u32(b+4)!=2U){out.message="Only GLB 2.0 is supported";return out;}if(u32(b+8)!=n){out.message="GLB declared length does not match file size";return out;}std::size_t p=12;while(p+8<=n){std::uint32_t len=u32(b+p),type=u32(b+p+4);p+=8;if(static_cast<std::size_t>(len)>n-p){out.message="GLB chunk exceeds file bounds";return out;}if(type==0x4E4F534AU)out.json.assign(reinterpret_cast<const char*>(b+p),len);p+=len;}if(out.json.empty()){out.message="GLB JSON chunk missing";return out;}}else out.json.assign(reinterpret_cast<const char*>(b),n);if(!has(out.json,"\"asset\"")||!has(out.json,"\"version\"")||!has(out.json,"2.0")){out.message="Not a recognizable glTF 2.0 document";return out;}out.valid=true;out.message=has(out.json,"\"meshes\"")?"glTF 2.0 mesh metadata found":"Valid glTF 2.0 document; no mesh array found";return out;}
}
